diff --git a/src/slugify.js b/src/slugify.js
index 775eb1e..509a6e8 100644
--- a/src/slugify.js
+++ b/src/slugify.js
@@ -1,10 +1,34 @@
+// Latin letters whose ASCII spelling is not supplied by canonical decomposition.
+const latinSpellings = new Map();
+for (const [letters, spelling] of [
+	["æǣǽ", "ae"], ["œ", "oe"], ["ß", "ss"], ["þ", "th"],
+	["ðđɗƌ", "d"], ["øǿɵơ", "o"], ["łƚɫ", "l"],
+	["ħɦ", "h"], ["ıɨ", "i"], ["ŋƞɲ", "n"], ["ŧƭʈ", "t"],
+	["ƀɓƃ", "b"], ["ƈȼ", "c"], ["đɖ", "d"], ["əɛɇ", "e"],
+	["ƒ", "f"], ["ǥɠ", "g"], ["ƙĸ", "k"], ["ƥ", "p"],
+	["ɋ", "q"], ["ɍɽ", "r"], ["ƨʂ", "s"], ["ʉư", "u"],
+	["ʋ", "v"], ["ƴɏ", "y"], ["ƶȥʐ", "z"], ["ƕ", "hv"],
+	["ƿ", "w"], ["ȝ", "y"], ["ꜳ", "aa"], ["ꜵ", "ao"],
+	["ꜷ", "au"], ["ꜹꜻ", "av"], ["ꜽ", "ay"], ["ꝏ", "oo"],
+	["ꝡ", "vy"], ["ꝑꝓꝕ", "p"], ["ꝗꝙ", "q"], ["ꝁꝃꝅ", "k"],
+	["ꝋꝍ", "o"], ["ꞓ", "c"], ["ꞙ", "f"], ["ꞑ", "n"],
+	["ꞣ", "z"], ["ꞥ", "n"], ["ꞧ", "r"], ["ꞩ", "s"],
+	["ﬀ", "ff"], ["ﬁ", "fi"], ["ﬂ", "fl"], ["ﬃ", "ffi"],
+	["ﬄ", "ffl"], ["ﬅﬆ", "st"], ["ſ", "s"],
+]) {
+	for (const letter of letters) latinSpellings.set(letter, spelling);
+}
+
 /**
- * Turns a title into a URL slug: lower case, runs of anything that is not a letter or a digit become one hyphen, and
- * no hyphen at either end. Letters of every script are kept.
+ * Turns a title into a URL slug: Latin letters use their ASCII spelling,
+ * letters of other scripts are kept, and separator runs become one hyphen.
  */
 export function slugify(title) {
 	return title
 		.toLowerCase()
+		.normalize("NFD")
+		.replace(/\p{M}+/gu, "")
+		.replace(/\p{Script=Latin}/gu, letter => latinSpellings.get(letter) ?? letter)
 		.replace(/[^\p{L}\p{N}]+/gu, "-")
 		.replace(/^-+|-+$/g, "");
 }
diff --git a/test/slugify.test.js b/test/slugify.test.js
index 52bb499..24eecde 100644
--- a/test/slugify.test.js
+++ b/test/slugify.test.js
@@ -18,3 +18,12 @@ test("turns Latin letters with diacritics into ASCII", () => {
 	assert.equal(slugify("Crème Brûlée"), "creme-brulee");
 	assert.equal(slugify("Łódź"), "lodz");
 });
+
+test("handles strokes and ligatures", () => {
+	assert.equal(slugify("Øresund Æsir Straße Œuvre"), "oresund-aesir-strasse-oeuvre");
+	assert.equal(slugify("Đorđe Þór"), "dorde-thor");
+});
+
+test("handles separately written Latin accents", () => {
+	assert.equal(slugify("Cre\u0300me Bru\u0302le\u0301e"), "creme-brulee");
+});
